// Validation et transformation de la commande
const orderData = $input.first().json;

// Validation des champs requis
if (!orderData.items || orderData.items.length === 0) {
  throw new Error('La commande doit contenir au moins un article');
}

if (!orderData.customer) {
  throw new Error('Les informations client sont requises');
}

// Transformation au format HubRise
const hubRiseOrder = {
  status: 'new',
  service_type: orderData.service_type || 'delivery',
  service_type_ref: orderData.service_type === 'collection' ? 'collection' : 'delivery',
  expected_time: orderData.expected_time || null,
  customer: {
    first_name: orderData.customer.first_name || '',
    last_name: orderData.customer.last_name || '',
    phone: orderData.customer.phone || '',
    email: orderData.customer.email || '',
    delivery_notes: orderData.customer.delivery_notes || ''
  },
  items: orderData.items.map(item => ({
    product_name: item.name,
    sku_ref: item.sku_ref || item.id,
    quantity: item.quantity || 1,
    price: Math.round((item.price || 0) * 100).toString(),
    options: item.options?.map(opt => ({
      option_list_name: opt.option_list_name,
      name: opt.name,
      ref: opt.ref,
      price: Math.round((opt.price || 0) * 100).toString()
    })) || [],
    customer_notes: item.notes || ''
  })),
  payments: orderData.payment ? [{
    type: orderData.payment.type || 'cash',
    amount: Math.round((orderData.payment.amount || 0) * 100).toString()
  }] : [],
  total: Math.round((orderData.total || 0) * 100).toString(),
  custom_fields: {
    source: 'vapi_voice_order',
    conversation_id: orderData.conversation_id || ''
  }
};

// Ajouter l'adresse si livraison
if (orderData.service_type === 'delivery' && orderData.delivery_address) {
  hubRiseOrder.customer.address_1 = orderData.delivery_address.street || '';
  hubRiseOrder.customer.address_2 = orderData.delivery_address.street2 || '';
  hubRiseOrder.customer.city = orderData.delivery_address.city || '';
  hubRiseOrder.customer.postal_code = orderData.delivery_address.postal_code || '';
  hubRiseOrder.customer.country = orderData.delivery_address.country || 'FR';
}

return {
  json: {
    hubrise_order: hubRiseOrder,
    original_order: orderData
  }
};

// Préparer la réponse
const hubRiseResponse = $input.first().json;

return {
  json: {
    success: true,
    order_id: hubRiseResponse.id,
    status: hubRiseResponse.status,
    confirmation_code: hubRiseResponse.confirmation_code || hubRiseResponse.id?.slice(-6).toUpperCase(),
    message: `Commande ${hubRiseResponse.id} créée avec succès`,
    estimated_time: hubRiseResponse.expected_time || '30-45 minutes',
    details: {
      total: hubRiseResponse.total ? parseInt(hubRiseResponse.total) / 100 : 0,
      items_count: hubRiseResponse.items?.length || 0,
      service_type: hubRiseResponse.service_type
    }
  }
};

// Gestion des erreurs
const error = $input.first().json;

return {
  json: {
    success: false,
    error: error.message || 'Une erreur est survenue lors de la création de la commande',
    code: error.code || 'ORDER_CREATION_FAILED'
  }
};
